int main() {
    readAll();
    int n = num();
    // Trie as first-child / next-sibling lists; node 0 is the root.
    vector<int> child(1, -1), sibling(1, -1), parent(1, -1), endCount(1, 0);
    vector<char> letter(1, 0);
    vector<int> last(n);
