package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(num())
	// Trie as first-child / next-sibling lists; node 0 is the root.
	child, sibling, parent, endCount := []int32{-1}, []int32{-1}, []int32{-1}, []int32{0}
	letter := []byte{0}
	last := make([]int32, n)
	for w := 0; w < n; w++ {
		skipSpace()
		node := int32(0)
		for pos < len(data) && data[pos] > ' ' {
			c := data[pos]
			pos++
			k := child[node]
			for k >= 0 && letter[k] != c {
				k = sibling[k]
			}
			if k < 0 {
				k = int32(len(child))
				child = append(child, -1)
				sibling = append(sibling, child[node])
				parent = append(parent, node)
				endCount = append(endCount, 0)
				letter = append(letter, c)
				child[node] = k
			}
			node = k
		}
		endCount[node]++
		last[w] = node
	}
	// Parents are created before children, so one forward pass gives the number of
	// complete titles ending on each root-to-node path.
	onPath := make([]int64, len(child))
	for v := 1; v < len(child); v++ {
		onPath[v] = onPath[parent[v]] + int64(endCount[v])
	}
	var total int64
	for _, node := range last {
		total += onPath[node] - 1 // drop pairing a title with itself
	}
	fmt.Println(total)
}
